var config = $input.first().json;
var names = config.competitors.split(',').map(function(c) { return c.trim(); });
var urls = config.competitor_urls.split(',').map(function(u) { return u.trim(); });
var feeds = config.rss_feeds.split(',').map(function(r) { return r.trim(); });

return names.map(function(name, i) {
  return {
    json: {
      competitor: name,
      website_url: urls[i] || '',
      rss_feed: feeds[i] || '',
      keywords: config.keywords,
      openai_model: config.openai_model,
      slack_channel: config.slack_channel,
      email_recipient: config.email_recipient,
      notion_database_id: config.notion_database_id,
      google_sheets_id: config.google_sheets_id,
      report_date: config.report_date,
    }
  };
});

var html = $json.htmlContent || $json.data || '';
var competitor = $json.competitor || '';
var url = $json.website_url || '';

var titleMatch = html.match(/<title[^>]*>([^<]+)<\/title>/i);
var title = titleMatch ? titleMatch[1].trim() : competitor + ' - Official Website';

var descMatch = html.match(/<meta[^>]*name="description"[^>]*content="([^"]{1,500})"/i);
if (!descMatch) {
  descMatch = html.match(/<meta[^>]*content="([^"]{1,500})"[^>]*name="description"/i);
}
var description = descMatch ? descMatch[1].trim() : 'No description found';

var h1Match = html.match(/<h1[^>]*>([^<]{1,200})<\/h1>/i);
var h1 = h1Match ? h1Match[1].replace(/<[^>]+>/g, '').trim() : '';

return {
  json: {
    source: 'website',
    competitor: competitor,
    title: title,
    headline: title,
    url: url,
    content: description + (h1 ? ' | ' + h1 : ''),
    summary: description.substring(0, 300),
    published_at: new Date().toISOString(),
  }
};

var competitor = $("Set Current Competitor").item.json.competitor;
var items = $input.all();
if (!items || items.length === 0) return [];
return items.map(function(item) {
  return {
    json: {
      source: 'company_rss',
      competitor: competitor,
      title: item.json.title || '',
      headline: item.json.title || '',
      url: item.json.link || item.json.url || '',
      content: (item.json.contentSnippet || item.json.content || '').substring(0, 500),
      summary: (item.json.contentSnippet || '').substring(0, 200),
      published_at: item.json.isoDate || item.json.pubDate || new Date().toISOString(),
    }
  };
});

var competitor = $("Set Current Competitor").item.json.competitor;
var items = $input.all();
if (!items || items.length === 0) return [];
return items.map(function(item) {
  return {
    json: {
      source: 'google_news',
      competitor: competitor,
      title: item.json.title || '',
      headline: item.json.title || '',
      url: item.json.link || item.json.url || '',
      content: (item.json.contentSnippet || item.json.content || '').substring(0, 500),
      summary: (item.json.contentSnippet || '').substring(0, 200),
      published_at: item.json.isoDate || item.json.pubDate || new Date().toISOString(),
    }
