});

var competitor = $("Set Current Competitor").item.json.competitor;
var items = $input.all();
if (!items || items.length === 0) return [];
return items.map(function(item) {
  return {
    json: {
      source: 'reddit',
      competitor: competitor,
      title: item.json.title || '',
      headline: item.json.title || '',
      url: item.json.link || item.json.url || '',
      content: (item.json.contentSnippet || item.json.content || '').substring(0, 500),
      summary: (item.json.contentSnippet || '').substring(0, 200),
      published_at: item.json.isoDate || item.json.pubDate || new Date().toISOString(),
    }
  };
});

var aiContent = '';
if ($json.choices && $json.choices[0] && $json.choices[0].message) {
  aiContent = $json.choices[0].message.content || '';
}
if (!aiContent) {
  aiContent = '# Analysis Temporarily Unavailable\n\nAI analysis could not be generated for this competitor. Please check your OpenAI API key and try again. The data has been collected and saved.';
}

var competitor = $json.competitor || 'Unknown';
var reportDate = $json.report_date || new Date().toISOString().split('T')[0];
var articles = $json.articles || [];

var urgencyMatch = aiContent.match(/Urgency Score[:\s]*([0-9]+)/i);
var urgencyScore = urgencyMatch ? parseInt(urgencyMatch[1]) : 5;

var riskMatch = aiContent.match(/Risk Level[:\s]*(Low|Medium|High)/i);
var riskLevel = riskMatch ? riskMatch[1] : 'Medium';

var execMatch = aiContent.match(/## Executive Summary\n([\s\S]*?)(?=\n## |$)/);
var execSummary = execMatch ? execMatch[1].trim().substring(0, 600) : 'Analysis complete. See full report for findings.';

var sourceCount = {};
articles.forEach(function(a) {
  if (a.source) { sourceCount[a.source] = (sourceCount[a.source] || 0) + 1; }
});
var sourceSummary = Object.keys(sourceCount).map(function(k) { return k + ': ' + sourceCount[k] + ' item' + (sourceCount[k] !== 1 ? 's' : ''); }).join(', ') || 'website, company_rss, google_news, reddit';

return {
  json: {
    competitor: competitor,
    report_date: reportDate,
    markdown_report: aiContent,
    executive_summary: execSummary,
    urgency_score: urgencyScore,
    risk_level: riskLevel,
    sources_monitored: sourceSummary,
    total_articles: articles.length,
    notion_database_id: $json.notion_database_id || '',
    google_sheets_id: $json.google_sheets_id || '',
    slack_channel: $json.slack_channel || '',
    email_recipient: $json.email_recipient || '',
  }
};

var competitor = $json.competitor || 'Unknown';
var reportDate = $json.report_date || $now.toFormat('yyyy-MM-dd');
var slackChannel = $json.slack_channel || 'competitor-intel';
var emailRecipient = $json.email_recipient || '';

return {
