    report_date: reportDate,
    slack_channel: slackChannel,
    email_recipient: emailRecipient,
    competitors_monitored: competitor,
    competitor: competitor,
    urgency_score: $json.urgency_score || 5,
    risk_level: $json.risk_level || 'Medium',
    executive_summary: $json.executive_summary || '',
    sources_monitored: $json.sources_monitored || '',
    total_articles: $json.total_articles || 0,
    markdown_report: $json.markdown_report || '',
  }
};

