lines.push('• Reddit community discussions');
lines.push('');
lines.push('*Reports saved to:*');
lines.push(':notebook: Notion — Full AI intelligence reports with urgency scores and recommended actions');
lines.push(':bar_chart: Google Sheets — Structured data for trend analysis');
lines.push('');
lines.push(':mag: Open your Notion database to review findings and recommended actions.');
