    slack_message: lines.join('\n'),
    slack_channel: channel,
    email_recipient: emailRecipient,
    report_title: title,
    report_date: reportDate,
    competitors_monitored: competitors,
  }
};

var reportDate = $json.report_date || new Date().toISOString().split('T')[0];
var reportTitle = $json.report_title || 'Daily Competitor Intelligence Report';
