html += '<table style="width: 100%; border-collapse: collapse; margin: 16px 0; font-size: 14px;">';
html += '<tr style="background: #eff6ff;"><td style="padding: 12px 16px; border: 1px solid #dbeafe; font-weight: 600;">Data Source</td><td style="padding: 12px 16px; border: 1px solid #dbeafe; font-weight: 600;">Coverage</td></tr>';
html += '<tr><td style="padding: 10px 16px; border: 1px solid #e5e7eb;">Website Monitoring</td><td style="padding: 10px 16px; border: 1px solid #e5e7eb;">Homepage content, titles, descriptions analyzed</td></tr>';
html += '<tr style="background: #f9fafb;"><td style="padding: 10px 16px; border: 1px solid #e5e7eb;">Company RSS Feeds</td><td style="padding: 10px 16px; border: 1px solid #e5e7eb;">Blog posts and press announcements collected</td></tr>';
html += '<tr><td style="padding: 10px 16px; border: 1px solid #e5e7eb;">Google News</td><td style="padding: 10px 16px; border: 1px solid #e5e7eb;">Press mentions and news coverage captured</td></tr>';
html += '<tr style="background: #f9fafb;"><td style="padding: 10px 16px; border: 1px solid #e5e7eb;">Reddit Discussions</td><td style="padding: 10px 16px; border: 1px solid #e5e7eb;">Community sentiment and discussions tracked</td></tr>';
html += '<tr><td style="padding: 10px 16px; border: 1px solid #e5e7eb;">AI Analysis</td><td style="padding: 10px 16px; border: 1px solid #e5e7eb;">GPT-4o intelligence reports with urgency scores</td></tr>';
html += '</table>';
html += '<h2 style="color: #1e40af; font-size: 18px;">Where To Find Your Reports</h2>';
