html += '<strong>Notion Database</strong> — Full markdown intelligence reports per competitor including executive summaries, urgency scores (1-10), risk levels (Low/Medium/High), and recommended actions.';
html += '</div>';
html += '<div style="background: #eff6ff; border-left: 4px solid #3b82f6; padding: 16px; border-radius: 8px; margin-bottom: 24px;">';
