html += '<li>Track changes week-over-week using the Google Sheets Intelligence Log</li>';
html += '</ol>';
html += '<hr style="border: none; border-top: 1px solid #e5e7eb; margin: 24px 0;"/>';
html += '<p style="color: #9ca3af; font-size: 12px; text-align: center;">Automatically generated by AI Competitor Monitoring Platform on n8n.</p>';
html += '</div></body></html>';

return {
  json: {
    email_body: html,
    email_subject: reportTitle,
    email_recipient: emailRecipient,
    report_date: reportDate,
    competitors_monitored: competitors,
    slack_channel: slackChannel,
